async function i(r){const o=[];for await(const t of r.values())if(t.kind==="file")try{const e=await t.getFile();o.push(e)}catch(e){console.warn(`Failed to read file ${t.name}:`,e)}else if(t.kind==="directory")try{const e=await i(t);o.push(...e)}catch(e){console.warn(`Failed to read directory ${t.name}:`,e)}return o}async function n(){try{const r=await window.showDirectoryPicker();return await i(r)}catch(r){if(r.name==="AbortError")return[];throw console.error("Error accessing directory:",r),r}}export{n as openDirectoryAndGetFiles,i as scanDirectory};
